draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Draw a stick figure with a thought bubble
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 70);
  ctx.stroke();

  // Draw a thought bubble with a money symbol
  ctx.beginPath();
  ctx.arc(W/2 - 50 + 20*Math.sin(t), H/2 - 50 + 20*Math.cos(t), 30, 0, 2*Math.PI);
  ctx.stroke();
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('$', W/2 - 50 + 20*Math.sin(t), H/2 - 50 + 20*Math.cos(t));

  // Draw an intelligence symbol (lightbulb) in the background
  ctx.globalAlpha = 0.5;
  ctx.beginPath();
  ctx.arc(W/2 + 50, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.globalAlpha = 1;

  ctx.restore();
}
